export const PEACE_QUESTION_REGISTRY: Record<QuizDifficulty, { foundation: QuizQuestion[]; growth: QuizQuestion[]; mastery: QuizQuestion[]; }> = {
  easy: {
    foundation: PEACE_EASY_FOUNDATION,
    growth: PEACE_EASY_GROWTH,
    mastery: PEACE_EASY_MASTERY
  },
  medium: {
    foundation: PEACE_MEDIUM_FOUNDATION,
    growth: PEACE_MEDIUM_GROWTH,
    mastery: PEACE_MEDIUM_MASTERY
  },
  hard: {
    foundation: PEACE_HARD_FOUNDATION,
    growth: PEACE_HARD_GROWTH,
    mastery: PEACE_HARD_MASTERY
  },
};

export function getPeaceStageQuestions(difficulty: QuizDifficulty, stage: 1 | 2 | 3): QuizQuestion[] {
  const diffKey = (difficulty || 'easy').toLowerCase() as QuizDifficulty;
  const stageMap = PEACE_QUESTION_REGISTRY[diffKey] || PEACE_QUESTION_REGISTRY.easy;
  if (stage === 1) return stageMap.foundation;
  if (stage === 2) return stageMap.growth;
  return stageMap.mastery;
}

export function getPeaceLevelQuestions(difficulty: QuizDifficulty, level: number): QuizQuestion[] {
  const stage = level <= 10 ? 1 : level <= 20 ? 2 : 3;
  const stagePool = getPeaceStageQuestions(difficulty, stage);
  const offset = (level - 1) % 10;
  const startIndex = offset * 5;
  return stagePool.slice(startIndex, startIndex + 5);
}
